@pytest.mark.pre_alloc_mutable
def test_gas_cost(
    state_test: StateTestFiller,
    pre: Alloc,
    tx_data_hex: str,
    expected_post: dict,
) -> None:
    """Ori Pomerantz qbzzt1@gmail.com."""
    coinbase = Address("0x2adc25665018aa1fe0e6bc666dac8fc2697ff9ba")
    sender = Address("0x56724d001b4f2a2888a81971a64aad37cd43f881")
    contract = Address("0xccdcf3ff42c8382abeef05bb8949f975a6bc345c")

    env = Environment(
        fee_recipient=coinbase,
        number=1,
        timestamp=1000,
        prev_randao=0x20000,
        base_fee_per_gas=10,
        gas_limit=100000000,
    )

    pre[sender] = Account(balance=0xBA1A9CE0BA1A9CE, nonce=0)
    pre[contract] = Account(
        balance=0xBA1A9CE0BA1A9CE,
        nonce=0,
        code=(
            Op.MSTORE(
                offset=0x200,
                value=Op.DIV(Op.CALLDATALOAD(offset=0x0), Op.EXP(0x2, 0xF8)),
            )
            + Op.MSTORE(
                offset=0x340,
                value=Op.AND(
                    Op.DIV(Op.CALLDATALOAD(offset=0x0), Op.EXP(0x2, 0xE8)),
                    0xFFFF,
                ),
            )
            + Op.MSTORE(offset=0x260, value=0x11)
            + Op.JUMPDEST
            + Op.JUMPI(pc=0x76, condition=Op.ISZERO(Op.MLOAD(offset=0x260)))
            + Op.MSTORE(
                offset=0x260, value=Op.SUB(Op.MLOAD(offset=0x260), 0x1)
            )
            + Op.MSTORE8(
                offset=Op.ADD(Op.ADD(0x0, 0x100), Op.MLOAD(offset=0x220)),
                value=0x61,
            )
            + Op.MSTORE8(
                offset=Op.ADD(
                    Op.ADD(Op.ADD(0x0, 0x100), Op.MLOAD(offset=0x220)),
                    0x1,
                ),
                value=0xDA,
            )
            + Op.MSTORE8(
                offset=Op.ADD(
                    Op.ADD(Op.ADD(0x0, 0x100), Op.MLOAD(offset=0x220)),
                    0x2,
                ),
                value=0x7A,
            )
            + Op.MSTORE(
                offset=0x220, value=Op.ADD(Op.MLOAD(offset=0x220), 0x3)
            )
            + Op.JUMP(pc=0x24)
            + Op.JUMPDEST
            + Op.MSTORE8(
                offset=Op.ADD(Op.ADD(0x0, 0x100), Op.MLOAD(offset=0x220)),
                value=Op.MLOAD(offset=0x200),
            )
            + Op.MSTORE8(
                offset=Op.ADD(
                    Op.ADD(Op.ADD(0x0, 0x100), Op.MLOAD(offset=0x220)),
                    0x1,
                ),
                value=0x0,
            )
            + Op.MSTORE(
                offset=0x220, value=Op.ADD(Op.MLOAD(offset=0x220), 0x2)
            )
            + Op.PUSH1[0x1B]
            + Op.CODECOPY(dest_offset=0x0, offset=Op.PUSH2[0xFB], size=Op.DUP1)
            + Op.PUSH2[0x240]
            + Op.MSTORE
            + Op.MSTORE(
                offset=0x280,
                value=Op.CREATE(
                    value=0x0, offset=0x0, size=Op.MUL(0x100, 0x2)
                ),
            )
            + Op.MSTORE(offset=0x300, value=Op.GAS)
            + Op.POP(
                Op.CALL(
                    gas=0x10000,
                    address=Op.MLOAD(offset=0x280),
                    value=0x0,
                    args_offset=0x0,
                    args_size=0x0,
                    ret_offset=0x0,
                    ret_size=0x0,
                ),
            )
            + Op.MSTORE(offset=0x320, value=Op.GAS)
            + Op.SSTORE(
                key=0x0,
                value=Op.SUB(
                    Op.SUB(
                        Op.SUB(Op.MLOAD(offset=0x300), Op.MLOAD(offset=0x320)),
                        0x311,
                    ),
                    Op.MLOAD(offset=0x340),
                ),
            )
            + Op.SSTORE(key=0x1, value=Op.MLOAD(offset=0x340))
            + Op.STOP
            + Op.INVALID
            + Op.CODECOPY(
                dest_offset=Op.ADD(0x0, 0x100),
                offset=Op.ADD(0x0, 0x100),
                size=0x100,
            )
            + Op.RETURN(offset=Op.ADD(0x0, 0x100), size=0x100)
            + Op.STOP
        ),
        storage={0x0: 0x60A7},
    )

    tx_data = bytes.fromhex(tx_data_hex) if tx_data_hex else b""

    tx = Transaction(
        secret_key=Hash(
            "0x40ac0fc28c27e961ee46ec43355a094de205856edbd4654cf2577c2608d4ec1e"  # noqa: E501
        ),
        to=contract,
        data=tx_data,
        gas_limit=16777216,
        gas_price=10,
        nonce=0,
        value=1,
    )

    post = expected_post

    state_test(env=env, pre=pre, post=post, tx=tx)
